const item = $input.item.json;

// --- 1. Limpieza de HTML/entities en el contenido ---
const NAMED_ENTITIES = {
  amp: '&', quot: '"', apos: "'", nbsp: ' ', lt: '<', gt: '>',
  aacute: 'á', eacute: 'é', iacute: 'í', oacute: 'ó', uacute: 'ú',
  Aacute: 'Á', Eacute: 'É', Iacute: 'Í', Oacute: 'Ó', Uacute: 'Ú',
  ntilde: 'ñ', Ntilde: 'Ñ', uuml: 'ü', Uuml: 'Ü',
  iquest: '¿', iexcl: '¡',
  ldquo: '“', rdquo: '”', lsquo: '‘', rsquo: '’',
  mdash: '—', ndash: '–', hellip: '…'
};

function decodeEntities(text) {
  return text
    .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(Number(code)))
    .replace(/&#x([0-9a-fA-F]+);/g, (_, hex) => String.fromCharCode(parseInt(hex, 16)))
    .replace(/&([a-zA-Z]+);/g, (match, name) => (name in NAMED_ENTITIES ? NAMED_ENTITIES[name] : match));
}

function stripHtml(raw) {
  if (!raw) return '';
  let text = raw
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ');
  text = decodeEntities(text);
  return text.replace(/\s+/g, ' ').trim();
}

const cleanContent = stripHtml(item.raw_summary || '');
const cleanTitle = stripHtml(item.title || '');

// --- 2. Normalización de fecha a ISO 8601 UTC ---
// published_date ya viene en formato ISO (ej: "2026-07-12T03:40:00.000Z"),
// pero seguimos validando en vez de asumir que SIEMPRE será así.
let publishedAt = null;
if (item.published_date) {
  const dt = DateTime.fromISO(item.published_date, { zone: 'utc' });
  publishedAt = dt.isValid ? dt.toISO() : null;
}

// --- 3. Limpieza de URL (quitar parámetros de tracking) ---
let cleanLink = item.link || '';
try {
  const url = new URL(cleanLink);
  const trackingParams = ['utm_source', 'utm_medium', 'utm_campaign', 'utm_content', 'utm_term', 'ref', 'fbclid'];
  trackingParams.forEach(p => url.searchParams.delete(p));
  cleanLink = url.toString();
} catch (e) {
  // link inválido o vacío
}

// --- 4. Idioma ---
const languageBySource = {
  'El País': 'es',
  'elDiario.es': 'es',
  'El Mundo': 'es',
  'ABC': 'es',
  '20minutos': 'es',
  'La Vanguardia': 'es',
  'Europa Press': 'es',
  'El Español': 'es'
};
const language = languageBySource[item.source_name] || 'unknown';

return {
  json: {
    ...item,
    title: cleanTitle,
    content: cleanContent,
    published_date: publishedAt,
    link: cleanLink,
    language,
    normalization_valid: !!(cleanTitle && publishedAt && cleanLink)
  }
};
